sp_widget.client_script:
api.controller = function() {

    var c = this;

    c.filters = {
        technology: '',
        location: '',
        eventType: ''
    };


    c.applyFilters = function() {

        c.server.get({

            technology: c.filters.technology,

            location: c.filters.location,

            eventType: c.filters.eventType

        }).then(function(response) {

            c.data = response.data;

        });

    };


    c.clearFilters = function() {

        c.filters = {
            technology: '',
            location: '',
            eventType: ''
        };

        c.applyFilters();

    };

};

sp_widget.css:
/* =========================================================
   CAMPUS CONNECT — BROWSE VERIFIED EVENTS
   ========================================================= */

.cc-browse-events {

    width: 115%;

    padding: 26px 50px 35px 145px;

    box-sizing: border-box;

    font-family: "Segoe UI", Arial, sans-serif;

    background:transparent;
  
}


/* =========================================================
   HEADER
   ========================================================= */

.cc-browse-header {

    margin-bottom: 22px;
}

.cc-browse-header h1 {

    margin: 0;

    color: #102a43;

    font-size: 26px;

    font-weight: 700;
}

.cc-browse-header p {

    margin: 6px 0 0 0;

    color: #718096;

    font-size: 13px;
}


/* =========================================================
   FILTER PANEL
   ========================================================= */

.cc-filter-panel {

    display: flex;

    align-items: flex-end;

    gap: 12px;

    padding: 18px;

    margin-bottom: 18px;

    background: #ffffff;

    border: 1px solid #dce5ef;

    border-radius: 10px;

    box-shadow: 50px 3px 50px rgba(20, 45, 80, 0.05);
}


.cc-filter-item {

    flex: 1;

    min-width: 0;
}


.cc-filter-item label {

    display: block;

    margin-bottom: 6px;

    color: #34495e;

    font-size: 11px;

    font-weight: 600;
}


.cc-filter-control {

    width: 100%;

    height: 36px;

    padding: 0 10px;

    background: #ffffff;

    border: 1px solid #cbd8e8;

    border-radius: 5px;

    color: #243b53;

    font-size: 12px;

    outline: none;
}


.cc-filter-control:focus {

    border-color: #0879e8;

    box-shadow: 0 0 0 2px rgba(8, 121, 232, 0.08);
}


/* Clear */

.cc-clear-filter {

    height: 36px;

    padding: 0 15px;

    background: #ffffff;

    border: 1px solid #cbd8e8;

    border-radius: 5px;

    color: #23415f;

    font-size: 11px;

    font-weight: 600;

    cursor: pointer;

    white-space: nowrap;
}


.cc-clear-filter:hover {

    background: #f4f8fc;

    border-color: #9fb7d0;
}


/* =========================================================
   RESULT HEADER
   ========================================================= */

.cc-result-header {

    display: flex;

    align-items: center;

    justify-content: space-between;

    margin-bottom: 14px;

    color: #718096;

    font-size: 11px;
}


.cc-verified-label {

    padding: 5px 9px;

    background: #e9f8f0;

    border: 1px solid #c9ead8;

    border-radius: 5px;

    color: #217a4b;

    font-size: 10px;

    font-weight: 700;
}


/* =========================================================
   EVENT GRID
   ========================================================= */

.cc-browse-row {

    margin-left: -7px;

    margin-right: -7px;
}


.cc-browse-row > div {

    padding-left: 7px;

    padding-right: 7px;

    margin-bottom: 14px;
}


/* =========================================================
   EVENT CARD
   ========================================================= */

.cc-event-card {

    min-height: 300px;

    padding: 18px;

    box-sizing: border-box;

    background: #ffffff;

    border: 1px solid #dce5ef;

    border-radius: 10px;

    box-shadow: 0 4px 14px rgba(20, 45, 80, 0.06);

    transition:
        transform 0.18s ease,
        box-shadow 0.18s ease,
        border-color 0.18s ease;
}


.cc-event-card:hover {

    transform: translateY(-3px);

    border-color: #b9cde3;

    box-shadow:
        0 9px 22px rgba(20, 45, 80, 0.11);
}


/* =========================================================
   EVENT TOP
   ========================================================= */

.cc-event-top {

    display: flex;

    align-items: center;

    justify-content: space-between;

    margin-bottom: 13px;
}


.cc-event-type {

    display: inline-flex;

    align-items: center;

    padding: 5px 9px;

    background: #eaf3ff;

    border-radius: 5px;

    color: #0866c6;

    font-size: 10px;

    font-weight: 700;

    text-transform: capitalize;
}


.cc-event-fee {

    color: #1f7a4d;

    font-size: 11px;

    font-weight: 700;
}


/* =========================================================
   EVENT TITLE
   ========================================================= */

.cc-event-card h3 {

    margin: 0 0 8px 0;

    color: #102a43;

    font-size: 17px;

    font-weight: 700;

    line-height: 1.35;

    min-height: 45px;
}


/* =========================================================
   TECHNOLOGY TAGS
   ========================================================= */

.cc-tags {

    margin: 0 0 13px 0;

    color: #0879e8;

    font-size: 11px;

    font-weight: 600;

    line-height: 1.5;
}


/* =========================================================
   EVENT INFORMATION
   ========================================================= */

.cc-event-info {

    margin: 6px 0;

    color: #52677d;

    font-size: 11px;

    line-height: 1.4;
}


.cc-info-icon {

    display: inline-block;

    width: 20px;

    font-size: 12px;
}


/* =========================================================
   MAP
   ========================================================= */

.cc-map-btn {

    display: inline-block;

    margin-top: 3px;

    margin-bottom: 10px;

    color: #0879e8 !important;

    font-size: 11px;

    font-weight: 600;

    text-decoration: none !important;

    cursor: pointer;
}


.cc-map-btn:hover {

    color: #005bb5 !important;

    text-decoration: underline !important;
}


/* =========================================================
   VERIFICATION
   ========================================================= */

.cc-verification {

    display: inline-block;

    margin-bottom: 11px;

    padding: 4px 8px;

    background: #e9f8f0;

    border: 1px solid #c9ead8;

    border-radius: 4px;

    color: #217a4b;

    font-size: 9px;

    font-weight: 700;
}


/* =========================================================
   ACTIONS
   ========================================================= */

.cc-event-actions {

    display: flex;

    align-items: center;

    gap: 8px;

    margin-top: 5px;
}


.cc-details-btn,
.cc-register-btn {

    flex: 1;

    height: 34px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 5px;

    font-size: 11px;

    font-weight: 600;

    text-decoration: none !important;

    cursor: pointer;
}


/* Details */

.cc-details-btn {

    background: #ffffff;

    border: 1px solid #cbd8e8;

    color: #23415f !important;
}


.cc-details-btn:hover {

    background: #f5f9fd;

    border-color: #9fb7d0;

    color: #102a43 !important;
}


/* Register */

.cc-register-btn {

    background: #0879e8;

    border: 1px solid #0879e8;

    color: #ffffff !important;
}


.cc-register-btn:hover {

    background: #0668c7;

    border-color: #0668c7;

    color: #ffffff !important;
}


/* =========================================================
   NO EVENTS
   ========================================================= */

.cc-no-events {

    padding: 50px 20px;

    text-align: center;

    background: #ffffff;

    border: 1px solid #dce5ef;

    border-radius: 10px;
}


.cc-no-events-icon {

    font-size: 32px;

    margin-bottom: 10px;
}


.cc-no-events h3 {

    margin: 0 0 6px 0;

    color: #102a43;

    font-size: 17px;
}


.cc-no-events p {

    margin: 0;

    color: #718096;

    font-size: 12px;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 992px) {

    .cc-browse-events {

        padding: 22px 20px 30px 20px;
    }

    .cc-filter-panel {

        flex-wrap: wrap;
    }

    .cc-filter-item {

        flex: 1 1 30%;
    }

}


@media (max-width: 600px) {

    .cc-browse-events {

        padding: 18px 15px 25px 15px;
    }

    .cc-filter-panel {

        flex-direction: column;

        align-items: stretch;
    }

    .cc-filter-item {

        width: 100%;
    }

    .cc-clear-filter {

        width: 100%;
    }

    .cc-result-header {

        align-items: flex-start;

        flex-direction: column;

        gap: 8px;
    }

}

sp_widget.script:
(function() {

    data.events = [];
    data.technologies = [];
    data.locations = [];
    data.eventTypes = [];


    /*
     * ----------------------------------------------------
     * FILTER VALUES
     * ----------------------------------------------------
     */

    var selectedTechnology =
        input && input.technology
            ? input.technology
            : '';

    var selectedLocation =
        input && input.location
            ? input.location
            : '';

    var selectedEventType =
        input && input.eventType
            ? input.eventType
            : '';


    /*
     * ----------------------------------------------------
     * EVENTS
     * ONLY VERIFIED EVENTS ARE ALLOWED
     * ----------------------------------------------------
     */

    var eventGR =
        new GlideRecord('x_snc_campus_con_0_events');


    // IMPORTANT:
    // Only Verified events are visible
    eventGR.addQuery(
        'verification_status',
        'verified'
    );


    /*
     * Technology filter
     */

    if (selectedTechnology) {

        eventGR.addQuery(
            'technology_tags',
            'CONTAINS',
            selectedTechnology
        );

    }


    /*
     * Location filter
     */

    if (selectedLocation) {

        eventGR.addQuery(
            'location',
            selectedLocation
        );

    }


    /*
     * Event Type filter
     */

    if (selectedEventType) {

        eventGR.addQuery(
            'event_type',
            selectedEventType
        );

    }


    /*
     * Nearest events first
     */

    eventGR.orderBy('event_date');

    eventGR.query();


    /*
     * ----------------------------------------------------
     * BUILD EVENT DATA
     * ----------------------------------------------------
     */

    while (eventGR.next()) {

        var feeDisplay =
            eventGR.getDisplayValue('fees');


        if (!feeDisplay || feeDisplay == '0') {

            feeDisplay = 'Free';

        }


        data.events.push({

            sys_id:
                eventGR.getUniqueValue(),

            event_name:
                eventGR.getDisplayValue('event_name'),

            organizer:
                eventGR.getDisplayValue('organizer'),

            event_date:
                eventGR.getDisplayValue('event_date'),

            location:
                eventGR.getDisplayValue('location'),

            event_type:
                eventGR.getDisplayValue('event_type'),

            technology_tags:
                eventGR.getDisplayValue('technology_tags'),

            fees:
                feeDisplay,

            verification_status:
                eventGR.getDisplayValue(
                    'verification_status'
                ),

            google_maps_link:
                eventGR.getValue(
                    'google_maps_link'
                )

        });

    }


    /*
     * ----------------------------------------------------
     * TECHNOLOGY FILTER OPTIONS
     * ----------------------------------------------------
     */

    var technologyMap = {};

    var techGR =
        new GlideRecord(
            'x_snc_campus_con_0_events'
        );


    techGR.addQuery(
        'verification_status',
        'verified'
    );

    techGR.query();


    while (techGR.next()) {

        var technologyText =
            techGR.getValue(
                'technology_tags'
            ) || '';


        var technologies =
            technologyText.split(/[,;•]/);


        for (var i = 0;
             i < technologies.length;
             i++) {

            var technology =
                technologies[i].trim();


            if (technology) {

                technologyMap[
                    technology.toLowerCase()
                ] = technology;

            }

        }

    }


    for (var technologyKey in technologyMap) {

        data.technologies.push(
            technologyMap[technologyKey]
        );

    }


    data.technologies.sort();


    /*
     * ----------------------------------------------------
     * LOCATION FILTER OPTIONS
     * ----------------------------------------------------
     */

    var locationMap = {};

    var locationGR =
        new GlideRecord(
            'x_snc_campus_con_0_events'
        );


    locationGR.addQuery(
        'verification_status',
        'verified'
    );

    locationGR.addNotNullQuery(
        'location'
    );

    locationGR.query();


    while (locationGR.next()) {

        var location =
            locationGR.getDisplayValue(
                'location'
            );


        if (location) {

            locationMap[
                location.toLowerCase()
            ] = location;

        }

    }


    for (var locationKey in locationMap) {

        data.locations.push(
            locationMap[locationKey]
        );

    }


    data.locations.sort();


    /*
     * ----------------------------------------------------
     * EVENT TYPE FILTER OPTIONS
     * ----------------------------------------------------
     */

    var eventTypeMap = {};

    var typeGR =
        new GlideRecord(
            'x_snc_campus_con_0_events'
        );


    typeGR.addQuery(
        'verification_status',
        'verified'
    );

    typeGR.query();


    while (typeGR.next()) {

        var eventType =
            typeGR.getDisplayValue(
                'event_type'
            );


        if (eventType) {

            eventTypeMap[
                eventType.toLowerCase()
            ] = eventType;

        }

    }


    for (var typeKey in eventTypeMap) {

        data.eventTypes.push(
            eventTypeMap[typeKey]
        );

    }


    data.eventTypes.sort();


})();
